mapper.select:
SELECT b.id, b.name, b.business_type, b.address, b.longitude, b.latitude, b.intro, ( SELECT fr.public_url FROM business_file_relation bfr JOIN file_resource fr ON fr.id = bfr.file_resource_id WHERE bfr.business_id = b.id AND fr.status = 'ACTIVE' AND fr.deleted_at IS NULL ORDER BY bfr.sort_no ASC, bfr.file_resource_id ASC LIMIT 1 ) AS cover_image_url FROM business b WHERE b.status = 'ENABLED' AND b.deleted_at IS NULL
AND b.business_type = #{type}
ORDER BY b.business_type ASC, b.id ASC
